  for(i=0;i<=n;i++){L[i]=[];for(j=0;j<=m;j++)L[i][j]=0}
  for(i=n-1;i>=0;i--)for(j=m-1;j>=0;j--)
    L[i][j]=same(t[i].n,u[j].n)?L[i+1][j+1]+1:Math.max(L[i+1][j],L[i][j+1]);
