    function cell(f,shown){return '<td'+(shown?' class="pc"':'')+'><button class="vcell" data-a="vsay" data-t="'+esc(pp+' '+f)+tl('" aria-label="Pronounce ')+esc(pp+' '+f)+'">'+(shown?'<span class="pfs">'+esc(shown)+'</span><span class="pfl">'+esc(f)+'</span>':esc(f))+'</button></td>'}
