  var busy=(ui.tab==='quiz'&&ui.quiz&&ui.quiz.i<ui.quiz.qs.length)||(ui.tab==='translate'&&ui.tr&&ui.tr.i<ui.tr.qs.length)||(ui.tab==='verbs'&&ui.vq&&ui.vq.i<ui.vq.qs.length)||(ui.tab==='conv'&&ui.cv&&ui.cv.i<ui.cv.items.length);
