function exChips(s){
  return s.split(', ').map(function(x){
    var m=x.match(/^(der|die|das) (.*)$/);
    if(!m) return '<span class="chip-ex">'+esc(x)+'</span>';
    return '<span class="chip-ex '+ac(m[1])+'"><span class="art">'+m[1]+'</span> '+esc(m[2])+'</span>';
  }).join('');
}
// Which gender rule a noun follows (or that it has none)
var SUFFIX_RULES=[['ung','die'],['heit','die'],['keit','die'],['schaft','die'],['ion','die'],['tät','die'],['ur','die'],['ik','die'],['ie','die'],
  ['chen','das'],['lein','das'],['ment','das'],['um','das'],['ei','die'],['ling','der'],['ismus','der'],['or','der']];
var SEM={der:[[tl('Days, months and seasons are der'),['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag','Januar','Juli','Sommer','Winter','Frühling','Herbst']],
  [tl('Weather words are der'),['Regen','Schnee','Wind','Nebel','Sturm']],[tl('Most alcoholic drinks are der'),['Wein','Wodka','Schnaps']]]};
var _cmp=null;
function ruleFor(w){
  if(!w.art||!w.de||w.de.indexOf(' ')>-1) return null;
  var de=w.de, lo=de.toLowerCase(), art=w.art;
  function R(kind,text){return {kind:kind,text:text}}
  if(w.pl==='pl') return R('ok',tl('Plural-only word: plurals are always die'));
  for(var i=0;i<(SEM.der||[]).length;i++){ if(SEM.der[i][1].indexOf(de)>-1) return art==='der'?R('ok',SEM.der[i][0]):R('ex',tl('Exception: ')+SEM.der[i][0].toLowerCase()+tl(', but this one is ')+art); }
  if(art==='der'&&/er$/.test(lo)&&/\(male\)|teacher/.test(w.en)) return R('ok',tl('Male people who do something (-er) are der'));
  if(!_cmp) _cmp=allWords().filter(function(x){return x.art&&x.de.indexOf(' ')<0&&x.de.length>=3});
  var best=null;
  _cmp.forEach(function(x){var xl=x.de.toLowerCase();if(x!==w&&lo.length>xl.length+2&&lo.slice(-xl.length)===xl&&(!best||xl.length>best.de.length))best=x});
  if(best&&best.art===art) return R('ok',tl('Compound word: it takes the gender of its last part, ')+best.art+' '+best.de);
  if(de==='Bier') return R('ex',tl('Exception: most alcoholic drinks are der, but beer is das'));
  if(/\(female\)/.test(w.en)&&/in$/.test(de)) return art==='die'?R('ok',tl('Female people ending in -in are die')):null;
  if(art==='das'&&VERBS.some(function(v){return lo.slice(-v.inf.length)===v.inf&&lo.length>=v.inf.length}))
    return R('ok',tl('Verbs used as nouns are das'));
  for(var j=0;j<SUFFIX_RULES.length;j++){
    var sx=SUFFIX_RULES[j][0], a=SUFFIX_RULES[j][1];
    if(sx==='um'&&(lo.length<5||/aum$/.test(lo))) continue;
    if(sx==='ur'&&/eur$/.test(lo)) continue;
    if(lo.length>sx.length+1&&lo.slice(-sx.length)===sx)
      return a===art?R('ok',tl('Words ending in -')+sx+tl(' are ')+a):R('ex',tl('Exception: words ending in -')+sx+tl(' are usually ')+a+tl(', but this one is ')+art);
  }
  if(/e$/.test(lo)&&!/ee$/.test(lo)){
    if(art==='der'&&/(male|boy)/.test(w.en)&&!/female/.test(w.en)) return R('ok',tl('Male people ending in -e are der'));
    return art==='die'?R('ok',tl('Most nouns ending in -e are die')):R('ex',tl('Exception: most nouns ending in -e are die, but this one is ')+art);
  }
  if(/^ge/.test(lo)&&lo.length>4) return art==='das'?R('ok',tl('Nouns starting with Ge- are often das')):R('ex',tl('Exception: nouns starting with Ge- are often das, but this one is ')+art);
  return R('none',tl('No rule: learn this one by heart'));
}
function ruleHtml(w){var r=ruleFor(w);return r?'<p class="rhint r-'+r.kind+'">'+(r.kind==='ok'?'✓ ':r.kind==='ex'?'⚠ ':'✎ ')+esc(r.text)+'</p>':''}
